#[effects(alloc)]
fn swap(st: &mut Vec<i64>) -> u8 {
    if 2 > st.len() {
        return 1;
    }
    let b: i64 = match st.pop() {
        None => 0,
        Some(x) => x,
    };
    let a: i64 = match st.pop() {
        None => 0,
        Some(x) => x,
    };
    st.push(b);
    st.push(a);
    0
}
